package com.anthony6996.hardcorecompass;
import com.anthony6996.hardcorecompass.command.CompassCommand;import com.anthony6996.hardcorecompass.config.ConfigManager;import com.anthony6996.hardcorecompass.listener.*;import com.anthony6996.hardcorecompass.manager.*;import com.anthony6996.hardcorecompass.storage.PlayerData;import org.bukkit.plugin.java.JavaPlugin;
public final class HardcoreCompassPlugin extends JavaPlugin{private LivesManager livesManager;private CompassManager compassManager;private PlayerData playerData;private ConfigManager configManager;@Override public void onEnable(){saveDefaultConfig();configManager=new ConfigManager(this);playerData=new PlayerData(this);livesManager=new LivesManager(configManager,playerData);compassManager=new CompassManager(this,configManager);compassManager.registerRecipe();TeleportManager teleport=new TeleportManager(this,configManager,playerData);getServer().getPluginManager().registerEvents(new PlayerJoinListener(livesManager,compassManager,configManager),this);getServer().getPluginManager().registerEvents(new PlayerDeathListener(livesManager,compassManager,teleport,configManager),this);getServer().getPluginManager().registerEvents(new PlayerRespawnListener(configManager),this);getServer().getPluginManager().registerEvents(new CompassInteractionListener(compassManager,configManager),this);getServer().getPluginManager().registerEvents(new CompassCraftListener(compassManager,configManager),this);CompassCommand command=new CompassCommand(this,livesManager,configManager,compassManager);getCommand("hcompass").setExecutor(command);getCommand("hcompass").setTabCompleter(command);getLogger().info("HardcoreCompass enabled for Paper/Purpur 1.21.1.");}@Override public void onDisable(){if(livesManager!=null)livesManager.save();}public PlayerData getPlayerData(){return playerData;}public void reloadPluginConfig(){configManager.reload();compassManager.registerRecipe();}}
